#!/bin/bash
# PRIVATE PROTOTYPE. Copies the Remote Play sign-in client values out of the chiaki-ng source into
# a generated Swift file, so they are not typed into or committed to this repository.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
python3 - "$HERE/../chiaki-ng/gui/include/psnaccountid.h" "$HERE/RGPChiaki/Sources/RGPChiaki/PSNClient.generated.swift" <<'P'
import re, sys
src = open(sys.argv[1]).read()
cid = re.search(r'CLIENT_ID\s*=\s*"([^"]+)"', src).group(1)
sec = re.search(r'CLIENT_SECRET\s*=\s*"([^"]+)"', src).group(1)
open(sys.argv[2], "w").write(
    "// GENERATED by gen-psn-client.sh from chiaki-ng. Do not edit; not checked in.\n"
    "enum PSNClient {\n    static let id = \"%s\"\n    static let secret = \"%s\"\n}\n" % (cid, sec))
print("generated")
P
